import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Login.css';

const Login: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    
    // Hardcoded customer credentials for testing
    if (email === 'customer1@gmail.com' && password === 'customer@1') {
      // Store user info in localStorage for demo purposes
      localStorage.setItem('currentUser', JSON.stringify({
        email: 'customer1@gmail.com',
        username: 'customer1',
        role: 'customer',
        mobile: '+94 77 123 4567',
        garageName: 'Lanka Auto Service',
        registrationNumber: 'REG-001'
      }));
      navigate('/dashboard');
      return;
    }
    
    // TODO: Implement real login logic
    console.log('Login attempt:', { email, password });
    alert('Invalid credentials. Use customer1@gmail.com / customer@1 for demo.');
  };

  const handleRegister = () => {
    navigate('/register');
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="company-header">
          <h1>Japan Lanka Enterprises</h1>
          <p>Management System</p>
        </div>
        
        <form onSubmit={handleLogin} className="login-form">
          <h2>Login</h2>
          
          <div className="form-group">
            <label htmlFor="email">Email Address</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="Enter your email address"
              required
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              required
            />
          </div>
          
          <button type="submit" className="login-btn">
            Login
          </button>
          
          <div className="register-section">
            <p>Don't have an account?</p>
            <button 
              type="button" 
              className="register-btn"
              onClick={handleRegister}
            >
              Register
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Login;
